PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS "Admin" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"username" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" TEXT NOT NULL DEFAULT 'ADMIN',"isActive" INTEGER NOT NULL DEFAULT 1,"lastLoginAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "Admin_email_key" ON "Admin"("email");
CREATE UNIQUE INDEX IF NOT EXISTS "Admin_username_key" ON "Admin"("username");
CREATE TABLE IF NOT EXISTS "Category" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT,"image" TEXT,"icon" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,"isActive" INTEGER NOT NULL DEFAULT 1,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "Category_slug_key" ON "Category"("slug");
CREATE INDEX IF NOT EXISTS "Category_slug_idx" ON "Category"("slug");
CREATE TABLE IF NOT EXISTS "Vehicle" ("id" TEXT NOT NULL PRIMARY KEY,"categoryId" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"brand" TEXT NOT NULL,"model" TEXT NOT NULL,"year" INTEGER,"shortDescription" TEXT,"description" TEXT,"fuelType" TEXT,"transmission" TEXT,"engine" TEXT,"bodyType" TEXT,"color" TEXT,"seatCount" INTEGER,"doorCount" INTEGER,"luggageCapacity" TEXT,"hasAirConditioning" INTEGER NOT NULL DEFAULT 1,"dailyPrice" REAL,"weeklyPrice" REAL,"monthlyPrice" REAL,"deposit" REAL,"showPrice" INTEGER NOT NULL DEFAULT 1,"minimumRentalDays" INTEGER NOT NULL DEFAULT 1,"dailyKmLimit" INTEGER,"status" TEXT NOT NULL DEFAULT 'AVAILABLE',"featured" INTEGER NOT NULL DEFAULT 0,"budgetFriendly" INTEGER NOT NULL DEFAULT 0,"showOnHomepage" INTEGER NOT NULL DEFAULT 0,"sortOrder" INTEGER NOT NULL DEFAULT 0,"mainImage" TEXT,"viewCount" INTEGER NOT NULL DEFAULT 0,"seoTitle" TEXT,"seoDescription" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,"deletedAt" DATETIME,CONSTRAINT "Vehicle_categoryId_fkey" FOREIGN KEY("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS "Vehicle_slug_key" ON "Vehicle"("slug");
CREATE INDEX IF NOT EXISTS "Vehicle_categoryId_idx" ON "Vehicle"("categoryId");
CREATE INDEX IF NOT EXISTS "Vehicle_status_idx" ON "Vehicle"("status");
CREATE INDEX IF NOT EXISTS "Vehicle_featured_idx" ON "Vehicle"("featured");
CREATE INDEX IF NOT EXISTS "Vehicle_budgetFriendly_idx" ON "Vehicle"("budgetFriendly");
CREATE INDEX IF NOT EXISTS "Vehicle_slug_idx" ON "Vehicle"("slug");
CREATE TABLE IF NOT EXISTS "VehicleImage" ("id" TEXT NOT NULL PRIMARY KEY,"vehicleId" TEXT NOT NULL,"imageUrl" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "VehicleImage_vehicleId_fkey" FOREIGN KEY("vehicleId") REFERENCES "Vehicle"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "RentalRequest" ("id" TEXT NOT NULL PRIMARY KEY,"vehicleId" TEXT NOT NULL,"fullName" TEXT NOT NULL,"phone" TEXT NOT NULL,"startDate" DATETIME,"endDate" DATETIME,"pickupLocation" TEXT,"message" TEXT,"status" TEXT NOT NULL DEFAULT 'NEW',"adminNote" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,"deletedAt" DATETIME,CONSTRAINT "RentalRequest_vehicleId_fkey" FOREIGN KEY("vehicleId") REFERENCES "Vehicle"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "RentalRequest_status_idx" ON "RentalRequest"("status");
CREATE INDEX IF NOT EXISTS "RentalRequest_createdAt_idx" ON "RentalRequest"("createdAt");
CREATE TABLE IF NOT EXISTS "Settings" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT DEFAULT 1,"siteName" TEXT NOT NULL,"companyLegalName" TEXT NOT NULL,"phone" TEXT NOT NULL,"whatsapp" TEXT NOT NULL,"email" TEXT NOT NULL,"address" TEXT NOT NULL,"mersisNo" TEXT NOT NULL,"tradeRegistryNo" TEXT NOT NULL,"tradeRegistryOffice" TEXT NOT NULL,"googleMapsUrl" TEXT,"instagramUrl" TEXT,"facebookUrl" TEXT,"tiktokUrl" TEXT,"workingHours" TEXT,"logoUrl" TEXT,"faviconUrl" TEXT,"footerDescription" TEXT,"seoTitle" TEXT,"seoDescription" TEXT,"campaignEnabled" INTEGER NOT NULL DEFAULT 1,"campaignTitle" TEXT DEFAULT 'Kurumsal kiralamada size özel çözümler',"campaignText" TEXT DEFAULT 'İhtiyacınıza uygun aracı birlikte belirleyelim. Hızlı bilgi ve teklif için WhatsApp üzerinden bize ulaşın.',"campaignImageUrl" TEXT DEFAULT '/og.png',"campaignButtonText" TEXT DEFAULT 'WhatsApp''tan Teklif Al',"updatedAt" DATETIME NOT NULL);
